<template><div class="page-container" v-loading="loading"><section class="page-hero"><div><h2>群组管理</h2><p>群组自动发现；群管操作统一排队执行。</p></div><ElButton @click="load">刷新</ElButton></section><ElCard class="content-card"><ElTable :data="groups"><ElTableColumn prop="title" label="群组" min-width="180"/><ElTableColumn prop="id" label="群 ID" min-width="160"/><ElTableColumn label="状态" width="100"><template #default="{row}"><ElTag :type="row.active?'success':'info'">{{row.active?'已接入':'已离开'}}</ElTag></template></ElTableColumn><ElTableColumn label="禁言" width="90"><template #default="{row}">{{row.muted?'已禁言':'正常'}}</template></ElTableColumn><ElTableColumn label="操作" min-width="310"><template #default="{row}"><ElButton size="small" @click="act(row,'sync')">同步</ElButton><ElButton size="small" :type="row.muted?'success':'warning'" @click="act(row,row.muted?'unmute_all':'mute_all')">{{row.muted?'开群 · 允许发言':'关群 · 全群禁言'}}</ElButton><ElButton size="small" @click="open(row)">设置</ElButton></template></ElTableColumn></ElTable><ElEmpty v-if="!groups.length" description="将机器人加入群组并授予管理员权限，收到事件后自动显示"/></ElCard><ElDialog v-model="dialog" title="群组设置" width="min(620px,94vw)"><ElForm label-position="top"><ElFormItem label="欢迎消息"><ElSwitch v-model="form.welcomeEnabled"/></ElFormItem><ElFormItem label="欢迎文案（支持 {name}、{group}）"><ElInput v-model="form.welcomeText" type="textarea" :rows="3" maxlength="2000"/></ElFormItem><ElFormItem label="统计保留天数"><ElInputNumber v-model="form.statsDays" :min="1" :max="365"/></ElFormItem><ElFormItem label="操作日志保留天数"><ElInputNumber v-model="form.logDays" :min="1" :max="365"/></ElFormItem></ElForm><template #footer><ElButton @click="dialog=false">取消</ElButton><ElButton type="primary" @click="save">保存</ElButton></template></ElDialog></div></template>
<script setup lang="ts">
import {getGroups,saveSettings,doAction,type Group} from '@/api/guard'
import {ElMessage,ElMessageBox} from 'element-plus'
const groups=ref<Group[]>([]),loading=ref(false),dialog=ref(false),selected=ref(''),form=reactive<any>({})
async function load(){loading.value=true;try{groups.value=await getGroups()}finally{loading.value=false}}
function open(g:any){selected.value=g.id;Object.assign(form,{welcomeEnabled:g.settings.welcomeEnabled,welcomeText:g.settings.welcomeText,statsDays:g.settings.statsDays,logDays:g.settings.logDays});dialog.value=true}
async function save(){await saveSettings(selected.value,form);ElMessage.success('已保存');dialog.value=false;await load()}
async function act(g:any,kind:string){await ElMessageBox.confirm(`确认对“${g.title}”执行${kind==='mute_all'?'全群禁言':kind==='unmute_all'?'解除禁言':'同步'}？`,'群管操作');await doAction(g.id,kind);ElMessage.success('已排队，请刷新查看结果或检查操作记录')}
onMounted(load)
</script>
